using System.IO.Compression;
using System.Security.Claims;
using CertificateManager.Application;
using CertificateManager.Domain;
using CertificateManager.Infrastructure;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;

var builder=WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<AppDbContext>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("Database")));
builder.Services.AddIdentity<ApplicationUser,IdentityRole>(o=>{o.Password.RequiredLength=12;o.Password.RequireNonAlphanumeric=true;o.Lockout.MaxFailedAccessAttempts=5;o.SignIn.RequireConfirmedAccount=false;}).AddEntityFrameworkStores<AppDbContext>().AddDefaultTokenProviders();
builder.Services.ConfigureApplicationCookie(o=>{o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;o.Cookie.SecurePolicy=CookieSecurePolicy.SameAsRequest;o.SlidingExpiration=true;o.ExpireTimeSpan=TimeSpan.FromHours(8);});
builder.Services.AddAuthorization(o=>{o.AddPolicy("Read",p=>p.RequireRole(Roles.Reader,Roles.Operator,Roles.Administrator));o.AddPolicy("Operate",p=>p.RequireRole(Roles.Operator,Roles.Administrator));o.AddPolicy("Admin",p=>p.RequireRole(Roles.Administrator));});
builder.Services.AddAntiforgery(o=>o.HeaderName="X-XSRF-TOKEN"); builder.Services.AddRateLimiter(o=>o.AddFixedWindowLimiter("api",x=>{x.PermitLimit=100;x.Window=TimeSpan.FromMinutes(1);x.QueueLimit=0;}));
builder.Services.Configure<SmtpOptions>(builder.Configuration.GetSection(SmtpOptions.Section));builder.Services.AddScoped<INotificationService,SmtpNotificationService>();builder.Services.AddSingleton<ICertificateGenerator,CertificateGenerator>();builder.Services.AddProblemDetails();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();
var app=builder.Build(); app.UseExceptionHandler(); app.Use(async(ctx,next)=>{ctx.Response.Headers["X-Content-Type-Options"]="nosniff";ctx.Response.Headers["X-Frame-Options"]="DENY";ctx.Response.Headers["Referrer-Policy"]="no-referrer";ctx.Response.Headers["Content-Security-Policy"]="default-src 'self'; style-src 'self' 'unsafe-inline'";await next();}); app.UseRateLimiter(); app.UseAuthentication(); app.UseAuthorization();
if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();} app.UseDefaultFiles();app.UseStaticFiles();
var api=app.MapGroup("/api").RequireRateLimiting("api");
api.MapGet("/antiforgery",(Microsoft.AspNetCore.Antiforgery.IAntiforgery a,HttpContext c)=>{var t=a.GetAndStoreTokens(c);return Results.Ok(new{token=t.RequestToken});});
api.MapPost("/auth/login",async(LoginRequest r,SignInManager<ApplicationUser> sm,AppDbContext db,HttpContext ctx)=>{var result=await sm.PasswordSignInAsync(r.Email,r.Password,true,true);db.AuditLogs.Add(new(){Action="USER_LOGIN",EntityType="User",EntityId=r.Email,IpAddress=ctx.Connection.RemoteIpAddress?.ToString(),Result=result.Succeeded?"Success":"Failure"});await db.SaveChangesAsync();return result.Succeeded?Results.Ok():Results.Unauthorized();});
api.MapPost("/auth/logout",async(SignInManager<ApplicationUser> sm)=>{await sm.SignOutAsync();return Results.NoContent();}).RequireAuthorization();
api.MapGet("/me",(ClaimsPrincipal u)=>Results.Ok(new{email=u.Identity!.Name,roles=u.Claims.Where(x=>x.Type==ClaimTypes.Role).Select(x=>x.Value)})).RequireAuthorization();
api.MapGet("/customers",async(AppDbContext db)=>await db.Customers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync()).RequireAuthorization("Read");
api.MapPost("/customers",async(CustomerInput r,AppDbContext db,ClaimsPrincipal u)=>{var c=new Customer{Name=r.Name.Trim(),Description=r.Description??"",CustomerNumber=r.CustomerNumber};db.Customers.Add(c);Audit(db,u,"CREATE_CUSTOMER","Customer",c.Id);await db.SaveChangesAsync();return Results.Created($"/api/customers/{c.Id}",c);}).RequireAuthorization("Admin");
api.MapGet("/environments",async(Guid? customerId,AppDbContext db)=>await db.Environments.AsNoTracking().Where(x=>customerId==null||x.CustomerId==customerId).OrderBy(x=>x.Name).ToListAsync()).RequireAuthorization("Read");
api.MapPost("/environments",async(EnvironmentInput r,AppDbContext db,ClaimsPrincipal u)=>{var e=new TargetEnvironment{CustomerId=r.CustomerId,Name=r.Name.Trim(),Description=r.Description??"",TenantReference=r.TenantReference,EnvironmentType=r.EnvironmentType};db.Environments.Add(e);Audit(db,u,"CREATE_ENVIRONMENT","Environment",e.Id);await db.SaveChangesAsync();return Results.Created($"/api/environments/{e.Id}",e);}).RequireAuthorization("Admin");
api.MapGet("/services",async(Guid? environmentId,AppDbContext db)=>await db.Services.AsNoTracking().Where(x=>environmentId==null||x.EnvironmentId==environmentId).OrderBy(x=>x.Name).ToListAsync()).RequireAuthorization("Read");
api.MapPost("/services",async(ServiceInput r,AppDbContext db,ClaimsPrincipal u)=>{var s=new ManagedService{EnvironmentId=r.EnvironmentId,Name=r.Name.Trim(),Description=r.Description??"",ApplicationClientId=r.ApplicationClientId,ExternalReference=r.ExternalReference};db.Services.Add(s);Audit(db,u,"CREATE_SERVICE","Service",s.Id);await db.SaveChangesAsync();return Results.Created($"/api/services/{s.Id}",s);}).RequireAuthorization("Admin");
api.MapGet("/certificates",async(string? search,int page,int pageSize,AppDbContext db)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize==0?25:pageSize,1,100);var q=db.Certificates.AsNoTracking().Include(x=>x.Service).ThenInclude(x=>x.Environment).ThenInclude(x=>x.Customer).Where(x=>string.IsNullOrEmpty(search)||x.Name.Contains(search)||x.Thumbprint.Contains(search)||x.PrimaryOwnerEmail.Contains(search));var total=await q.CountAsync();var rows=await q.OrderBy(x=>x.ValidUntil).Skip((page-1)*pageSize).Take(pageSize).ToListAsync();var now=DateTimeOffset.UtcNow;var items=rows.Select(x=>new{x.Id,x.Name,x.Thumbprint,x.ValidUntil,daysRemaining=(int)Math.Floor((x.ValidUntil-now).TotalDays),health=CertificateHealth.Calculate(x.ValidUntil,now),x.PrimaryOwnerEmail,x.DeploymentStatus,service=x.Service.Name,environment=x.Service.Environment.Name,customer=x.Service.Environment.Customer.Name});return Results.Ok(new{items,total,page,pageSize});}).RequireAuthorization("Read");
api.MapPost("/certificates/generate",async(GenerateCertificateRequest r,AppDbContext db,ICertificateGenerator generator,ClaimsPrincipal user)=>{var service=await db.Services.Include(x=>x.Environment).ThenInclude(x=>x.Customer).SingleOrDefaultAsync(x=>x.Id==r.ServiceId);if(service is null)return Results.NotFound();var generated=generator.Generate(r,user.FindFirstValue(ClaimTypes.NameIdentifier)!,service.Environment.Customer.Name,service.Environment.Name,service.Name,service.ApplicationClientId);db.Certificates.Add(generated.Metadata);if(r.PreviousCertificateId is Guid previous){var old=await db.Certificates.FindAsync(previous);if(old is null)return Results.BadRequest(new{error="Previous certificate not found"});old.ReplacementCertificateId=generated.Metadata.Id;}Audit(db,user,r.PreviousCertificateId is null?"CREATE_CERTIFICATE":"RENEW_CERTIFICATE","Certificate",generated.Metadata.Id);await db.SaveChangesAsync();return Results.Ok(new{generated.Metadata.Id,generated.Metadata.Name,generated.Metadata.Thumbprint,generated.Metadata.ValidUntil,generated.Metadata.RenewalDueAt,password=generated.Password,pfx=Convert.ToBase64String(generated.Pfx),cer=Convert.ToBase64String(generated.Cer),calendar=Convert.ToBase64String(generated.Calendar),package=Convert.ToBase64String(generated.Package)});}).RequireAuthorization("Operate");
api.MapGet("/certificates/{id:guid}",async(Guid id,AppDbContext db)=>{var c=await db.Certificates.AsNoTracking().Include(x=>x.Service).ThenInclude(x=>x.Environment).ThenInclude(x=>x.Customer).SingleOrDefaultAsync(x=>x.Id==id);return c is null?Results.NotFound():Results.Ok(new{certificate=c,health=CertificateHealth.Calculate(c.ValidUntil,DateTimeOffset.UtcNow),privateKeyAvailable=false});}).RequireAuthorization("Read");
api.MapPost("/certificates/{id:guid}/mark-deployed",async(Guid id,AppDbContext db,ClaimsPrincipal u)=>{var c=await db.Certificates.FindAsync(id);if(c is null)return Results.NotFound();c.DeploymentStatus=DeploymentStatus.DeploymentConfirmed;c.DeploymentConfirmedAt=DateTimeOffset.UtcNow;c.DeploymentConfirmedByUserId=u.FindFirstValue(ClaimTypes.NameIdentifier);Audit(db,u,"MARK_DEPLOYED","Certificate",id);await db.SaveChangesAsync();return Results.NoContent();}).RequireAuthorization("Operate");
api.MapPost("/certificates/{id:guid}/decommission",async(Guid id,AppDbContext db,ClaimsPrincipal u)=>{var c=await db.Certificates.FindAsync(id);if(c is null)return Results.NotFound();c.Status=CertificateStatus.Decommissioned;Audit(db,u,"DECOMMISSION_CERTIFICATE","Certificate",id);await db.SaveChangesAsync();return Results.NoContent();}).RequireAuthorization("Admin");
api.MapGet("/certificates/{id:guid}/calendar",async(Guid id,AppDbContext db)=>{var c=await db.Certificates.Include(x=>x.Service).ThenInclude(x=>x.Environment).ThenInclude(x=>x.Customer).SingleOrDefaultAsync(x=>x.Id==id);return c is null?Results.NotFound():Results.File(CalendarGenerator.Generate(c,c.Service.Environment.Customer.Name,c.Service.Environment.Name,c.Service.Name),"text/calendar",$"{c.Name}-renewal.ics");}).RequireAuthorization("Read");
api.MapGet("/dashboard",async(AppDbContext db)=>{var now=DateTimeOffset.UtcNow;var dates=await db.Certificates.Where(x=>x.Status!=CertificateStatus.Decommissioned).Select(x=>x.ValidUntil).ToListAsync();return Results.Ok(new{total=dates.Count,healthy=dates.Count(x=>(x-now).TotalDays>60),expiring60=dates.Count(x=>(x-now).TotalDays is >30 and <=60),expiring30=dates.Count(x=>(x-now).TotalDays is >14 and <=30),expiring14=dates.Count(x=>(x-now).TotalDays is >7 and <=14),critical=dates.Count(x=>(x-now).TotalDays is >0 and <=7),expired=dates.Count(x=>x<=now)});}).RequireAuthorization("Read");
api.MapGet("/audit",async(AppDbContext db)=>await db.AuditLogs.AsNoTracking().OrderByDescending(x=>x.Timestamp).Take(500).ToListAsync()).RequireAuthorization("Admin");
app.MapFallbackToFile("index.html");
await SeedAsync(app.Services);await app.RunAsync();
static void Audit(AppDbContext db,ClaimsPrincipal u,string action,string entity,object id)=>db.AuditLogs.Add(new(){Action=action,EntityType=entity,EntityId=id.ToString(),UserId=u.FindFirstValue(ClaimTypes.NameIdentifier),Result="Success"});
static async Task SeedAsync(IServiceProvider services){using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();await db.Database.EnsureCreatedAsync();var roles=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();foreach(var role in new[]{Roles.Reader,Roles.Operator,Roles.Administrator})if(!await roles.RoleExistsAsync(role))await roles.CreateAsync(new(role));var users=scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();if(await users.FindByEmailAsync("admin@localhost") is null){var user=new ApplicationUser{UserName="admin@localhost",Email="admin@localhost",DisplayName="Local Administrator",EmailConfirmed=true};var result=await users.CreateAsync(user,Environment.GetEnvironmentVariable("SEED_ADMIN_PASSWORD")??"ChangeMe!123456");if(result.Succeeded)await users.AddToRoleAsync(user,Roles.Administrator);}}
record LoginRequest(string Email,string Password); record CustomerInput(string Name,string? Description,string? CustomerNumber); record EnvironmentInput(Guid CustomerId,string Name,string? Description,string? TenantReference,EnvironmentType EnvironmentType); record ServiceInput(Guid EnvironmentId,string Name,string? Description,string? ApplicationClientId,string? ExternalReference);
public partial class Program { }
